/// <summary>
/// CB434_BasePriceVersion4StandardCosting, pass custom fields
/// </summary>
[ExtensionOf(classStr(GUPItemBasePriceUpdateValidJob))]
internal final class METGUPItemBasePriceUpdateValidJob_Extension
{
}

Method.Source:
/// <summary>
/// init custom fields
/// </summary>
/// <param name = "_selectionObject"></param>
protected void addBasePriceExtendedFields(SysDaSelection _selectionObject)
{
    next addBasePriceExtendedFields(_selectionObject);
    _selectionObject
        .add(fieldStr(GUPItemBasePrice, METVendClaimEnabled));
}

/// <summary>
/// CB434, after GUPItemBasePrice records are inserted, create standard costing entries
/// for all BasePriceInventoryCost records with no ToDate in this operation batch.
/// </summary>
/// <param name = "_operationGuid">Guid identifying the GUPItemBasePrice records inserted in this run</param>
public void postUpdateValidBasePrice(SysGuid _operationGuid)
{
   // next postUpdateValidBasePrice(_operationGuid);

    if (GUPParameters::find().METCreateItemPrice)
    {
        GUPItemBasePrice itemBasePrice, itembasePriceUpdate;

        while select itemBasePrice
            group by itemBasePrice.ItemId, itemBasePrice.InventDimId, itemBasePrice.PriceType, itemBasePrice.FromDate, itemBasePrice.ToDate, itembasePrice.OperationGuid
          where itemBasePrice.OperationGuid   == _operationGuid
              && itemBasePrice.PriceType       == GUPBasePriceType::BasePriceInventoryCost
              && itemBasePrice.ToDate          == dateNull()
        {
            itembasePriceUpdate = GUPItemBasePrice::findByDateRanges(itemBasePrice.ItemId, itemBasePrice.PriceType, itemBasePrice.InventDimId, itemBasePrice.FromDate, itemBasePrice.ToDate, itemBasePrice.OperationGuid);
            itembasePriceUpdate.inventItemPriceCreation();
        }
    }
}
